[ExtensionOf(classStr(Global))]
public static final class AVAGlobalCls_Extension
{       
}

Method.Source:
/// <summary>
/// Researches the form data source
/// </summary>
/// <param name = "_common">The buffer</param>
public static void formDataSourceResearch_AVA(Common _common)
{
    FormObjectSet formObjectSet;

    if (_common && _common != null && FormDataUtil::getFormDataSource(_common))
    {
        formObjectSet = FormDataUtil::getFormDataSource(_common);
        formObjectSet.research(true);
    }
}

/// <summary>
/// Returns the info log message
/// </summary>
/// <param name = "_startPos">If provided starting with the given position, otherwise the current position.</param>
/// <returns>The concatenated info log message</returns>
public static str getInfoLogMessage_AVA(int _startPos = Global::infologLine())
{
    str msg;

    for (int currentLine = _startPos + 1; currentLine <= Global::infologLine(); currentLine++)
    {
        msg = strFmt('%1%2', (strLen(msg) > 0 ? strFmt('%1 ', msg) : msg), infolog.text(currentLine));
    }

    return msg;
}

/// <summary>
/// Checks if a query filter exists
/// (Filter set up by the user via the grid filter control)
/// </summary>
/// <param name = "_fds">The form data source</param>
/// <param name = "_tableId">The table id</param>
/// <param name = "_fieldName">The field name</param>
/// <returns>true if the query filter exists, otherwise false</returns>
public static boolean queryFilterExists_AVA(FormDataSource _fds, TableId _tableId, FieldName _fieldName)
{
    boolean exist = false;
    QueryRun qr;
    Query q;
    QueryFilter qFilter;
    QueryBuildDataSource qbds;

    qr = _fds.queryRun();

    if (qr)
    {
        q = qr.query();
        qbds = q.dataSourceTable(_tableId);
        qFilter = q.findQueryFilter(qbds, _fieldName);
        exist = (qFilter && qFilter.value());
    }

    return exist;
}

/// <summary>
/// Converts a list to a container
/// </summary>
/// <param name = "_list">The list to convert</param>
/// <param name = "_removeEmpty">Indicates if empty elements should be removed</param>
/// <returns>The container with the list elements</returns>
public static container listElements2Con_AVA(List _list, boolean _removeEmpty = true)
{
    container con;
    ListIterator iterator = new ListIterator(_list);

    while (iterator.more())
    {
        anytype value = iterator.value();

        if (_removeEmpty && !value)
        {
            iterator.next();
            continue;
        }

        con += value;

        iterator.next();
    }

    return con;
}
